const textureLoader = new THREE.TextureLoader()
const fabricTextures = {
  color: textureLoader.load('data:image/jpeg;base64,'),
  normal: textureLoader.load('data:image/jpeg;base64,'),
  roughness: textureLoader.load('data:image/jpeg;base64,'),
  ao: textureLoader.load('data:image/jpeg;base64,'),
}
for (const tex of Object.values(fabricTextures)) {
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
}
fabricTextures.normal.colorSpace = THREE.LinearSRGBColorSpace
fabricTextures.roughness.colorSpace = THREE.LinearSRGBColorSpace
