// ─── Cushions ────────────────────────────────────────────────────────────────

const cushionColors = [
  { color: 0xc4956a, sheen: 0xe8b888 }, // warm sand
  { color: 0xa85a3a, sheen: 0xd4845a }, // terracotta
  { color: 0x6b5e54, sheen: 0x9a8d82 }, // taupe
  { color: 0xd4c4b0, sheen: 0xf0e6d8 }, // cream
  { color: 0x8b4513, sheen: 0xc47030 }, // saddle brown
  { color: 0x2c2420, sheen: 0x5a4a40 }, // espresso
  { color: 0xbc8f6f, sheen: 0xe0b898 }, // camel
]

const spread = 5
const spreadZ = 2.5
const bodies = cushionColors.map((c, i) => {
  const angle = (i / cushionColors.length) * Math.PI * 2
  const rOffset = 0.5 // 0 to 1
  const r = spread * (Math.random() * (1 - rOffset) + rOffset)
  const z = spreadZ * (Math.random() * 2 - 1)
  return {
    position: [Math.cos(angle) * r, Math.sin(angle) * r * 0.7, z],
    rotation: [Math.random() * Math.PI * 2, Math.random() * Math.PI * 2, Math.random() * Math.PI * 2],
    color: new THREE.Color(c.color),
    sheenColor: new THREE.Color(c.sheen),
  }
})

function createClothBody() {
  const geometry = new Cushion(params.cushionSize, params.cushionSubdivisions)
  return new ClothBodyManagerGPU({ position: geometry.position, index: geometry.index, uv: geometry.uv, bodies }, renderer, scene, {
    numSubsteps: params.numSubsteps,
    gravity: params.gravity,
    groundY: undefined,
    pressure: params.pressure,
    pressureRampTime: params.pressureRampTime,
    pressureStiffness: params.pressureStiffness,
    timescale: params.timescale,
    damping: params.damping,
    stretchingCompliance: params.stretchingCompliance,
    bendingCompliance: params.bendingCompliance,
    collisionRadius: params.collisionRadius,
    collisionFriction: params.collisionFriction,
    collisionDamping: params.collisionDamping,
    groundFriction: params.groundFriction,
    attractorStrength: params.attractorStrength,
    attractorPosition: params.attractorPosition,
    attractorRadius: params.attractorRadius,
    attractorRadiusMax: params.attractorRadiusMax,
    wanderStrength: params.wanderStrength,
    wanderSpeed: params.wanderSpeed,
    wrinklesEnabled: params.wrinklesEnabled,
    wrinkleFrequency: params.wrinkleFrequency,
    wrinkleStrength: params.wrinkleStrength,
    wrinkleSmoothingTime: params.wrinkleSmoothingTime,
    wrinkleGrazeAttenuation: params.wrinkleGrazeAttenuation,
    wrinkleThreshold: params.wrinkleThreshold,
    wrinkleScale: params.wrinkleScale,
    wrinkleTurbulence2D: params.wrinkleTurbulence2D,
    wrinkleTurbulence2DFrequency: params.wrinkleTurbulence2DFrequency,
    wrinkleTurbulence: params.wrinkleTurbulence,
    wrinkleTurbulenceFrequency: params.wrinkleTurbulenceFrequency,
    fabricTextures,
    cushionSize: params.cushionSize,
  })
}

