function updateAttractorDebug() {
  const [x, y, z] = params.attractorPosition
  attractorRadiusSphere.position.set(x, y, z)
  attractorRadiusSphere.scale.setScalar(params.attractorRadius)
  attractorRadiusMaxSphere.position.set(x, y, z)
  attractorRadiusMaxSphere.scale.setScalar(params.attractorRadiusMax)
}
updateAttractorDebug()

// ─── Mouse Sphere Collider ──────────────────────────────────────────────────

const mouseSphereDebug = new THREE.Mesh(
  new THREE.SphereGeometry(1, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0xff4400, wireframe: true }),
)
mouseSphereDebug.visible = false
scene.add(mouseSphereDebug)

const raycaster = new THREE.Raycaster()
const mouseNDC = new THREE.Vector2()
const mousePlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0)
const mouseWorldPos = new THREE.Vector3()
let mouseOnScreen = false

addEventListener('pointermove', (e) => {
  mouseNDC.set((e.clientX / innerWidth) * 2 - 1, -(e.clientY / innerHeight) * 2 + 1)
  raycaster.setFromCamera(mouseNDC, camera)
  raycaster.ray.intersectPlane(mousePlane, mouseWorldPos)
  mouseOnScreen = true
})

addEventListener('pointerleave', () => {
  mouseOnScreen = false
})

// ─── Post-Processing (N8AO + TRAA) ──────────────────────────────────────────

const scenePass = pass(scene, camera)
scenePass.setMRT(
  mrt({
    output: output,
    velocity: velocity,
  }),
)

const scenePassColor = scenePass.getTextureNode('output')
const scenePassDepth = scenePass.getTextureNode('depth')
const scenePassVelocity = scenePass.getTextureNode('velocity')

const aoPass = n8ao(scenePassDepth, null, camera)
aoPass.resolutionScale = params.aoResolutionScale
aoPass.radius = 0.63
aoPass.intensity = 2.87
aoPass.distanceFalloff = 4.84
aoPass.denoiseRadius = 12

const aoValue = pow(aoPass.getTextureNode().r, aoPass.intensity)
const compositedRGB = scenePassColor.rgb.mul(vec3(aoValue))
const traaPass = traa(vec4(compositedRGB, scenePassColor.a), scenePassDepth, scenePassVelocity, camera)
const traaNoAO = traa(scenePassColor, scenePassDepth, scenePassVelocity, camera)

// Apply alpha after TRAA (TRAA doesn't preserve alpha)
const fgAlpha = scenePassDepth.r.lessThan(1.0).select(float(1.0), float(0.0))
const finalWithAO = vec4(traaPass.rgb, fgAlpha)
const finalNoAO = vec4(traaNoAO.rgb, fgAlpha)

const renderPipeline = new THREE.RenderPipeline(renderer)

function updateAOPipeline() {
  renderPipeline.outputNode = params.aoEnabled ? finalWithAO : finalNoAO
  renderPipeline.needsUpdate = true
}
renderPipeline.outputNode = params.aoEnabled ? finalWithAO : finalNoAO

// ─── Debug ───────────────────────────────────────────────────────────────────

function setDebug(v) {
  stats.dom.style.display = v ? '' : 'none'
  debugOverlay.style.display = v ? '' : 'none'
  controls.enabled = v
  attractorRadiusSphere.visible = v
  attractorRadiusMaxSphere.visible = v
  keyLightHelper.visible = v
  fillLightHelper.visible = v
  rimLightHelper.visible = v
  if (!v) {
    mouseSphereDebug.visible = false
  }
  document.querySelectorAll('.nav, .hero, .bottom-left, .bottom-right').forEach((el) => {
    el.style.pointerEvents = v ? 'none' : ''
    el.style.opacity = v ? '0.2' : ''
  })
}

setDebug(params.debug)

addEventListener('keydown', (e) => {
  if (e.key === 'p' || e.key === 'P') {
    params.debug = !params.debug
    setDebug(params.debug)
    gui
      .controllersRecursive()
      .find((c) => c.property === 'debug')
      ?.updateDisplay()
  }
})

